(function(global){'use strict';var definition={"id":"m5-report","sceneId":"m5","title":"录井报告自动生成","version":"1.1.0","updated":"2026-11-01","status":"ready","methods":["nlp"],"lessonProtocol":"mudlogging-v1","tabs":{"background":{"label":"专业背景","lede":"跨表汇编报告之前，要先区分“气体升高”与“没有升高”、“接单根之后”与“并非接单根”。从语句归类开始，生成带字段出处的作业摘要。","judge":[{"label":"示例资料","value":"合成教学数据","desc":"共1392条合成语句：1152条训练、80条检查、160条留出。按32/8/16个句式模板组隔开；留出组的不同数字版本仍只算16种句式。"},{"label":"核心方法","value":"字符级 BiGRU","desc":"BiGRU接替逐条语句归类，利用前后文处理否定和时间关系；事实绑定接替反复抄录字段，再按模板生成摘要。"}],"sections":[{"no":1,"title":"真实背景","html":"<div class=\"context-two\"><p>录井报告把分层、气测、工况和样品记录组织为文字。传统做法需要在原表和笔记之间核对井段、数值与事件，再按章节汇编。</p><p>困难不只是把话写顺。同一个词在否定、转折和不同时间关系里可能有不同含义；分类结果与报告中的数值还必须能找到原始记录。</p></div><article class=\"technical-board\"><span class=\"mini\">现场全景 / 机制示意</span><h3>综合录井图把不同记录放在同一井深轴上。</h3><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"综合录井图以共同井深轴组织钻时、岩屑、气测和作业备注，示意数据\"><defs><marker id=\"prof-arrow-2773978315\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"20\" y=\"30\" width=\"720\" height=\"275\" rx=\"5\" fill=\"#fbf6e8\" stroke=\"#c4c9b5\"/><text x=\"45\" y=\"56\" class=\"prof-title\">井深 / m</text><text x=\"130\" y=\"56\" class=\"prof-title\">钻时</text><path d=\"M125 68V289\" stroke=\"#d6d9c5\"/><text x=\"240\" y=\"56\" class=\"prof-title\">岩屑描述</text><path d=\"M235 68V289\" stroke=\"#d6d9c5\"/><text x=\"370\" y=\"56\" class=\"prof-title\">全烃 / %</text><path d=\"M365 68V289\" stroke=\"#d6d9c5\"/><text x=\"540\" y=\"56\" class=\"prof-title\">作业备注</text><path d=\"M535 68V289\" stroke=\"#d6d9c5\"/><path d=\"M35 85H725\" stroke=\"#e3e4d2\"/><text x=\"48\" y=\"89\" class=\"\">2600</text><path d=\"M35 120H725\" stroke=\"#e3e4d2\"/><text x=\"48\" y=\"124\" class=\"\">2602</text><path d=\"M35 155H725\" stroke=\"#e3e4d2\"/><text x=\"48\" y=\"159\" class=\"\">2604</text><path d=\"M35 190H725\" stroke=\"#e3e4d2\"/><text x=\"48\" y=\"194\" class=\"\">2606</text><path d=\"M35 225H725\" stroke=\"#e3e4d2\"/><text x=\"48\" y=\"229\" class=\"\">2608</text><path d=\"M35 260H725\" stroke=\"#e3e4d2\"/><text x=\"48\" y=\"264\" class=\"\">2610</text><path data-depth-track=\"true\" d=\"M162.4 85.0L161.0 110.0L165.8 135.0L182.8 160.0L186.2 185.0L181.4 210.0L163.8 235.0L161.0 260.0\" stroke=\"#548d80\" stroke-width=\"3\" fill=\"none\"/><rect x=\"251\" y=\"85\" width=\"94\" height=\"88\" fill=\"#d3bd91\"/><rect x=\"251\" y=\"173\" width=\"94\" height=\"87\" fill=\"#a2b3a2\"/><text x=\"260\" y=\"131\" class=\"\">砂质较多</text><text x=\"260\" y=\"235\" class=\"\">泥质较多</text><path data-depth-track=\"true\" d=\"M405.0 85.0L406.2 110.0L411.0 135.0L483.0 160.0L465.0 185.0L415.8 210.0L409.8 235.0L411.0 260.0\" stroke=\"#6b9eaa\" stroke-width=\"3\" fill=\"none\"/><text x=\"552\" y=\"116\" class=\"\">岩屑特征变化</text><text x=\"552\" y=\"170\" class=\"\">气测升高</text><text x=\"552\" y=\"222\" class=\"\">转速调整</text></svg><p class=\"caption\">先建立井段、岩性、气测和工况之间的对应，再组织报告文字。图为成果结构示意。</p></article><div class=\"professional-course\"><article class=\"professional-concept\"><div class=\"concept-heading\"><span>A</span><h3>一份录井成果，不只是几段通顺的话</h3></div><div class=\"professional-grid\"><div><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"地质和工程记录共同组成录井成果\"><defs><marker id=\"prof-arrow-2397273906\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"16\" y=\"31\" width=\"234\" height=\"244\" rx=\"5\" fill=\"#e4dfcb\" stroke=\"#c4c9b5\"/><text x=\"34\" y=\"65\" class=\"prof-title\">地质记录</text><rect x=\"265\" y=\"31\" width=\"234\" height=\"244\" rx=\"5\" fill=\"#dde7df\" stroke=\"#c4c9b5\"/><text x=\"283\" y=\"65\" class=\"prof-title\">工程记录</text><rect x=\"514\" y=\"31\" width=\"234\" height=\"244\" rx=\"5\" fill=\"#f6f0df\" stroke=\"#c4c9b5\"/><text x=\"532\" y=\"65\" class=\"prof-title\">成果表达</text><text x=\"44\" y=\"119\" class=\"\">岩性与地层</text><text x=\"44\" y=\"169\" class=\"\">油气显示</text><text x=\"44\" y=\"219\" class=\"\">样品描述</text><text x=\"293\" y=\"119\" class=\"\">钻时与工况</text><text x=\"293\" y=\"169\" class=\"\">钻井液性质</text><text x=\"293\" y=\"219\" class=\"\">重要作业事件</text><text x=\"542\" y=\"119\" class=\"\">共同井深图</text><text x=\"542\" y=\"169\" class=\"\">主要井段说明</text><text x=\"542\" y=\"219\" class=\"\">交班摘要 / 综合报告</text></svg><p class=\"caption\">从现场记录到成果表达的专业层次；本课只截取交班摘要这一小部分。</p></div><dl><div><dt>地质记录</dt><dd>岩性描述、地层变化和油气显示；岩屑常记录颜色、粒度、结构、分选等特征。</dd></div><div><dt>工程记录</dt><dd>钻进参数、钻井液性质和重要作业事件，为解释曲线变化提供工况背景。</dd></div><div><dt>成果表达</dt><dd>综合录井图把记录放在共同井深轴上；文字说明再概括主要井段、显示和作业情况。</dd></div></dl></div></article><article class=\"professional-concept\"><div class=\"concept-heading\"><span>B</span><h3>观察到的事实，与解释性结论分层书写</h3></div><div class=\"professional-grid\"><div><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"录井报告中的事实与解释属于不同层次\"><defs><marker id=\"prof-arrow-1864383636\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"22\" y=\"25\" width=\"330\" height=\"243\" rx=\"5\" fill=\"#e1e8dc\" stroke=\"#c4c9b5\"/><rect x=\"410\" y=\"25\" width=\"329\" height=\"243\" rx=\"5\" fill=\"#eee1cf\" stroke=\"#c4c9b5\"/><text x=\"41\" y=\"58\" class=\"prof-title\">可回到原记录的事实</text><text x=\"430\" y=\"58\" class=\"prof-title\">需要更多资料的解释</text><text x=\"44\" y=\"109\" class=\"\">井段全烃持续升高</text><text x=\"44\" y=\"163\" class=\"\">岩屑呈现荧光</text><text x=\"44\" y=\"217\" class=\"\">接单根后返出短峰</text><text x=\"431\" y=\"109\" class=\"\">显示来自什么原因？</text><text x=\"431\" y=\"163\" class=\"\">与什么地层对应？</text><text x=\"431\" y=\"217\" class=\"\">能否支持流体与产能判断？</text><path d=\"M357 145H403\" stroke=\"#75988b\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#prof-arrow-1864383636)\"/><text x=\"39\" y=\"310\" class=\"\">摘要准确陈述事实；解释要说明所依据的地质、工况与验证资料。</text></svg><p class=\"caption\">相同的原始观测可以支持有限的描述，不能凭单个字段跳到产能或流体性质结论。</p></div><dl><div><dt>观测事实</dt><dd>例如某井段全烃升高、岩屑出现荧光、接单根后出现短峰，应能回到记录。</dd></div><div><dt>解释判断</dt><dd>把观测与工况、样品和其他资料结合，说明可能的成因与地层意义。</dd></div><div><dt>摘要范围</dt><dd>交班摘要先准确归纳本班记录。没有相应资料时，不补写工业油气层、储量或产能结论。</dd></div></dl></div></article><article class=\"professional-concept\"><div class=\"concept-heading\"><span>C</span><h3>井段、时刻和单位，共同决定句子能否用</h3></div><div class=\"professional-grid\"><div><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"深度基准与气体浓度单位的专业对应\"><defs><marker id=\"prof-arrow-625882031\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"19\" y=\"25\" width=\"348\" height=\"248\" rx=\"5\" fill=\"#e4e8d9\" stroke=\"#c4c9b5\"/><rect x=\"393\" y=\"25\" width=\"348\" height=\"248\" rx=\"5\" fill=\"#ede2cb\" stroke=\"#c4c9b5\"/><text x=\"38\" y=\"57\" class=\"prof-title\">空间和时间先对应</text><text x=\"412\" y=\"57\" class=\"prof-title\">数值与单位一起保留</text><path d=\"M84 95V159Q84 207 236 224\" fill=\"none\" stroke=\"#819d91\" stroke-width=\"8\"/><path d=\"M84 95V224\" stroke=\"#b59b76\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/><text x=\"106\" y=\"129\" class=\"\">MD：沿井眼</text><text x=\"106\" y=\"169\" class=\"\">TVD：垂直距离</text><text x=\"433\" y=\"119\" class=\"prof-equation\">0.5 %</text><text x=\"432\" y=\"163\" class=\"prof-equation\">= 5000 ppm</text><text x=\"420\" y=\"222\" class=\"\">值和单位不能拆开抄写</text><text x=\"29\" y=\"310\" class=\"\">地层沿井深关联；作业沿时间关联；返出资料还要考虑迟到。</text></svg><p class=\"caption\">字段对应的教学示例；实际报告还需遵循所用深度基准和单位体系。</p></div><dl><div><dt>井段范围</dt><dd>起止深度、MD/TVD和单位要一致；一条记录的值不能借给相邻井段。</dd></div><div><dt>时间对应</dt><dd>作业按时间串联，地层按井深串联；返出气测与井底来源之间还要考虑迟到。</dd></div><div><dt>数值单位</dt><dd>0.5%=5000 ppm，但两者不能直接抄成同一数值。保留原单位，并把换算与文字改写分开处理。</dd></div></dl></div></article></div><p class=\"professional-bridge\">报告先组织地质和作业事实，再形成解释。后面的BiGRU只承担交班语句归类，字段与数值仍来自原记录。</p><p class=\"source-line\">专业依据：<a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · 综合录井图的组成 ↗</a> · <a href=\"https://wiki.aapg.org/Show_evaluation\" target=\"_blank\" rel=\"noopener noreferrer\">AAPG · 显示评价与证据 ↗</a> · <a href=\"https://glossary.slb.com/en/terms/m/measured_depth\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · MD定义 ↗</a> · <a href=\"https://glossary.slb.com/en/terms/t/true_vertical_depth\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · TVD定义 ↗</a></p>"},{"no":2,"title":"技术前沿","html":"<p><a href=\"https://doi.org/10.3969/j.issn.1672-9803.2026.01.001\" target=\"_blank\" rel=\"noopener noreferrer\">海上油田录井专有大语言模型OffshoreGPT的构建与部署 ↗</a>：通过领域训练与微调适应专业术语、问答和作业语境。 本课用小型BiGRU讲清语句归类，不部署或复现OffshoreGPT。</p><p><a href=\"https://doi.org/10.2523/IPTC-24775-EA\" target=\"_blank\" rel=\"noopener noreferrer\">A Report Generation System for Well Logging Industry Based on Large Language Model and Retrieval Augmented Generation ↗</a>：检索增强与本地大语言模型结合，组织解释报告章节。 研究对象是测井解释报告；本课借鉴事实关联，数值由模板绑定。</p><p><a href=\"https://doi.org/10.3390/app16168089\" target=\"_blank\" rel=\"noopener noreferrer\">A Dual-Teacher Distilled MoE Agent for Complex Industrial Document Analysis ↗</a>：蒸馏、工具调用与MoE定位原始证据，判断数据一致性。 这是报告核对研究；本课只做字段ID关联，没有运行其MoE或智能体。</p>"},{"no":3,"title":"示例数据","html":"<p>共1392条合成语句：1152条训练、80条检查、160条留出。按32/8/16个句式模板组隔开；留出组的不同数字版本仍只算16种句式。</p>"},{"no":4,"title":"技术难度与参考方向","html":"<p>基础归类与模板容易实现；专业语境、跨表一致性和证据定位决定摘要是否可用。部署大模型还需要真实语料与独立评价。</p>"},{"no":5,"title":"术语对照表","html":"<table><tr><td>交班摘录</td><td>记录当班观察到的事实与事项。</td><td>待分类的中文输入。</td></tr><tr><td>事项归类</td><td>把语句放进相应的作业类别。</td><td>四类监督分类。</td></tr><tr><td>否定与转折</td><td>“没有升高”与“升高后回落”不同。</td><td>需要前后文的语义线索。</td></tr><tr><td>字符向量</td><td>把字转换成可学习的数字表示。</td><td>24维Embedding。</td></tr><tr><td>双向GRU</td><td>从两个方向读取整段文字。</td><td>本课实际运行的深度学习模型。</td></tr><tr><td>事实字段</td><td>原表里的井段、数值与描述。</td><td>带ID的键值记录。</td></tr><tr><td>证据定位</td><td>文字中的内容能回到原表。</td><td>字段ID关联与高亮。</td></tr><tr><td>模板组装</td><td>把明确字段放进指定句式。</td><td>确定性的文本生成。</td></tr><tr><td>RAG / 检索增强生成</td><td>先找资料，再让模型组织回答。</td><td>论文中的扩展方向；本课未部署LLM。</td></tr><tr><td>句式留出</td><td>相似表达整组隔开检查。</td><td>避免靠替换数字造成虚假的泛化。</td></tr><tr><td>综合录井图 / Mud log</td><td>沿同一井深轴并排展示多种记录。</td><td>多源数据的共同索引。</td></tr><tr><td>岩性描述</td><td>对颜色、粒度、结构等的专业记录。</td><td>需要保留原意的结构化文本。</td></tr><tr><td>观测与解释</td><td>记录看到什么，再说明可能意味着什么。</td><td>事实层与推断层分开表达。</td></tr></table>"}],"page":{"html":"demo/background.html","view":"background","height":1040}},"workflow":{"label":"案例流程","title":"先把记录读明白，再让每句话找到出处。","lead":["你收到160条留出交班摘录及关联事实表。先归为四类作业事项，再生成一份可点击数字、井段和原文来源的摘要，查看关键词规则为何会误读。"],"stats":[["流程","6步"],["核心算法","字符级 BiGRU"],["数据","同一份合成资料"]],"steps":[{"name":"约定摘要范围","role":"资料与任务","do":"给定一条交班摘录和关联事实表，输出作业事项及简短摘要，不补写未知试油结论。","effect":"一份有明确输入范围的作业摘要。","trap":"这是一份合成交班摘要实验，不是完整现场综合录井报告。BiGRU仍有分错的记录，页面保留全部输出；不能据此写入未经记录支持的地质结论。"},{"name":"关联井段与字段","role":"资料与任务","do":"为井段、气测值、描述和工况分配字段ID；语句中的数值沿用原记录。","effect":"能逐条定位的事实表。","trap":"这是一份合成交班摘要实验，不是完整现场综合录井报告。BiGRU仍有分错的记录，页面保留全部输出；不能据此写入未经记录支持的地质结论。"},{"name":"按句式组隔开","role":"资料与任务","do":"32种训练句式、8种检查句式、16种留出句式；仅替换数字不算新的语言表达。","effect":"独立句式的语句分类检查。","trap":"这是一份合成交班摘要实验，不是完整现场综合录井报告。BiGRU仍有分错的记录，页面保留全部输出；不能据此写入未经记录支持的地质结论。"},{"name":"用 BiGRU 理解语境","role":"重点 · AI处理","do":"字符编码后，双向GRU读取前后文，把否定和时间关系带入四类事件的判断。","effect":"四类得分与一个作业事项候选。","trap":"这是一份合成交班摘要实验，不是完整现场综合录井报告。BiGRU仍有分错的记录，页面保留全部输出；不能据此写入未经记录支持的地质结论。"},{"name":"把候选写回事实","role":"重点 · AI处理","do":"按记录ID取回字段，使用对应段落模板生成摘要。数字不由语句分类器自由生成。","effect":"带可点击字段出处的摘要初稿。","trap":"这是一份合成交班摘要实验，不是完整现场综合录井报告。BiGRU仍有分错的记录，页面保留全部输出；不能据此写入未经记录支持的地质结论。"},{"name":"对照并导出摘要","role":"资料与任务","do":"在同一条摘录上对照关键词规则与BiGRU，保留分错的例子，并导出正文及来源。","effect":"可以回到原表与原话的文本文件。","trap":"这是一份合成交班摘要实验，不是完整现场综合录井报告。BiGRU仍有分错的记录，页面保留全部输出；不能据此写入未经记录支持的地质结论。"}],"metrics":{"title":"基础算法与本课实现","html":"<svg class=\"network-diagram\" viewBox=\"0 0 960 148\" role=\"img\" aria-label=\"字符级 BiGRU从输入到结果的处理路径\"><rect x=\"10\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#eee5d4\" stroke=\"#b8b9aa\"/><text x=\"26\" y=\"64\" class=\"diagram-title\">字符与字向量</text><text x=\"26\" y=\"87\">本例实际输入形状</text><path d=\"M231 74H246\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"249\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#dce8df\" stroke=\"#b8b9aa\"/><text x=\"265\" y=\"64\" class=\"diagram-title\">双向GRU读前后文</text><text x=\"265\" y=\"87\">字符级 BiGRU</text><path d=\"M470 74H485\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"488\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#eee5d4\" stroke=\"#b8b9aa\"/><text x=\"504\" y=\"64\" class=\"diagram-title\">四类事件得分</text><text x=\"504\" y=\"87\">由训练资料拟合</text><path d=\"M709 74H724\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"727\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#eee5d4\" stroke=\"#b8b9aa\"/><text x=\"743\" y=\"64\" class=\"diagram-title\">事实绑定与模板摘要</text><text x=\"743\" y=\"87\">与原记录逐项对照</text></svg><p>24维字符向量、双向各24维GRU、4类线性输出。词表只从训练句式建立；摘要由明确的字段绑定生成，没有调用LLM。</p>"},"page":{"html":"demo/workflow.html","view":"workflow","height":1040}},"demo":{"label":"可运行示范","mode":"page","html":"demo/identify.html","view":"demo","height":1040,"intro":"选择一条原始摘录，对照两种归类与对应摘要。点击正文里的字段，原表中同一条记录会亮起。"}}};['background','workflow','demo'].forEach(function(name){var tab=definition.tabs[name],frame=null;function resize(event){if(frame&&event.source===frame.contentWindow&&event.data){var h=event.data.__lessonHeight;if(typeof h==='number'&&isFinite(h))frame.style.height=Math.max(700,Math.min(14000,h+2))+'px';}}tab.mount=function(root){tab.unmount();frame=document.createElement('iframe');frame.src="m5-report-case/"+(tab.page?tab.page.html:tab.html)+'?v='+definition.version;frame.setAttribute('title',"M5 · "+tab.label);frame.setAttribute('sandbox','allow-scripts allow-popups allow-popups-to-escape-sandbox allow-downloads');frame.setAttribute('referrerpolicy','no-referrer');frame.style.cssText='display:block;width:100%;height:1040px;border:0;border-radius:10px;background:#fcf7eb';global.addEventListener('message',resize);root.appendChild(frame);};tab.unmount=function(){global.removeEventListener('message',resize);if(frame)frame.remove();frame=null;};});global.Cases.register(definition);}(window));
